import React, { useState, useEffect } from 'react';
import api from '../api';

function CalendarView({ onDateSelect }) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [calendarData, setCalendarData] = useState({ daily: {}, weekly: {}, monthly: {} });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCalendarData();
  }, [currentDate]);

  const loadCalendarData = async () => {
    setLoading(true);
    try {
      const year = currentDate.getFullYear();
      const month = currentDate.getMonth() + 1;
      const data = await api.getCalendarData(year, month);
      setCalendarData(data);
    } catch (error) {
      console.error('Error loading calendar data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getDaysInMonth = (date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const daysInMonth = lastDay.getDate();
    const startingDayOfWeek = firstDay.getDay();

    const days = [];

    // Add empty cells for days before the month starts
    for (let i = 0; i < startingDayOfWeek; i++) {
      days.push(null);
    }

    // Add all days in the month
    for (let day = 1; day <= daysInMonth; day++) {
      days.push(new Date(year, month, day));
    }

    return days;
  };

  const getWeekStart = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day;
    d.setDate(diff);
    return d.toISOString().split('T')[0];
  };

  const getColorForPercentage = (percentage) => {
    if (percentage >= 90) return '#27ae60'; // Green
    if (percentage >= 50) return '#f39c12'; // Yellow
    if (percentage > 0) return '#e74c3c'; // Red
    return '#95a5a6'; // Gray
  };

  const handlePreviousMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const handleDateClick = (date) => {
    const dateStr = date.toISOString().split('T')[0];
    onDateSelect(dateStr);
  };

  const handleWeekClick = (weekStart) => {
    // Navigate to the tasks page with weekly view for this week
    const weekDate = new Date(weekStart);
    const dateStr = weekDate.toISOString().split('T')[0];
    onDateSelect(dateStr, 'weekly');
  };

  const days = getDaysInMonth(currentDate);
  const monthName = currentDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

  // Group days into weeks
  const weeks = [];
  for (let i = 0; i < days.length; i += 7) {
    weeks.push(days.slice(i, i + 7));
  }

  if (loading) {
    return <div className="loading">Loading calendar...</div>;
  }

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>Calendar View</h1>
        <p>Overview of task completion across your team</p>
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <button className="btn btn-secondary" onClick={handlePreviousMonth}>
          ← Previous
        </button>
        <h2>{monthName}</h2>
        <button className="btn btn-secondary" onClick={handleNextMonth}>
          Next →
        </button>
      </div>

      {/* Monthly Tasks Summary */}
      <div style={{ marginBottom: '30px', padding: '20px', backgroundColor: '#f8f9fa', borderRadius: '8px', border: '2px solid #e0e0e0' }}>
        <h3 style={{ marginBottom: '15px' }}>📈 Monthly Tasks</h3>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          <div style={{ 
            width: '100%', 
            height: '30px', 
            backgroundColor: '#e0e0e0', 
            borderRadius: '15px',
            overflow: 'hidden'
          }}>
            <div style={{
              width: `${calendarData.monthly.percentage || 0}%`,
              height: '100%',
              backgroundColor: getColorForPercentage(calendarData.monthly.percentage || 0),
              transition: 'width 0.3s ease'
            }}></div>
          </div>
          <div style={{ minWidth: '150px', textAlign: 'right', fontWeight: 'bold', fontSize: '18px' }}>
            {calendarData.monthly.completedTasks || 0} / {calendarData.monthly.totalTasks || 0} ({calendarData.monthly.percentage || 0}%)
          </div>
        </div>
      </div>

      <div className="calendar">
        <div className="calendar-header">
          <div className="calendar-day-name">Sun</div>
          <div className="calendar-day-name">Mon</div>
          <div className="calendar-day-name">Tue</div>
          <div className="calendar-day-name">Wed</div>
          <div className="calendar-day-name">Thu</div>
          <div className="calendar-day-name">Fri</div>
          <div className="calendar-day-name">Sat</div>
        </div>

        <div className="calendar-body">
          {weeks.map((week, weekIndex) => {
            // Get the week start date (Sunday)
            const firstDayOfWeek = week.find(day => day !== null);
            const weekStart = firstDayOfWeek ? getWeekStart(firstDayOfWeek) : null;
            const weekData = weekStart ? calendarData.weekly[weekStart] : null;
            const weekPercentage = weekData ? weekData.percentage : 0;
            const weekColor = getColorForPercentage(weekPercentage);

            return (
              <div 
                key={weekIndex} 
                style={{ 
                  display: 'contents',
                  position: 'relative'
                }}
              >
                <div style={{
                  gridColumn: '1 / -1',
                  display: 'grid',
                  gridTemplateColumns: 'repeat(7, 1fr)',
                  border: `3px solid ${weekColor}`,
                  borderRadius: '8px',
                  padding: '8px',
                  margin: '4px',
                  position: 'relative',
                  backgroundColor: 'white'
                }}>
                  {week.map((day, dayIndex) => {
                    if (!day) {
                      return <div key={dayIndex} className="calendar-day empty"></div>;
                    }

                    const dateStr = day.toISOString().split('T')[0];
                    const dayData = calendarData.daily[dateStr];
                    const percentage = dayData ? dayData.percentage : 0;
                    const color = getColorForPercentage(percentage);

                    return (
                      <div
                        key={dayIndex}
                        className="calendar-day"
                        onClick={() => handleDateClick(day)}
                        style={{
                          backgroundColor: color,
                          color: 'white',
                          cursor: 'pointer',
                          transition: 'all 0.2s'
                        }}
                        onMouseEnter={(e) => {
                          e.currentTarget.style.transform = 'scale(1.05)';
                          e.currentTarget.style.boxShadow = '0 4px 8px rgba(0,0,0,0.2)';
                        }}
                        onMouseLeave={(e) => {
                          e.currentTarget.style.transform = 'scale(1)';
                          e.currentTarget.style.boxShadow = 'none';
                        }}
                      >
                        <div className="day-number">{day.getDate()}</div>
                        {dayData && (
                          <div className="day-completion" style={{ fontSize: '11px', marginTop: '5px' }}>
                            {dayData.completedTasks}/{dayData.totalTasks}
                          </div>
                        )}
                      </div>
                    );
                  })}

                  {/* Week Circle Button */}
                  {weekStart && (
                    <div
                      onClick={(e) => {
                        e.stopPropagation();
                        handleWeekClick(weekStart);
                      }}
                      style={{
                        position: 'absolute',
                        right: '-20px',
                        top: '50%',
                        transform: 'translateY(-50%)',
                        width: '40px',
                        height: '40px',
                        borderRadius: '50%',
                        backgroundColor: weekColor,
                        border: '3px solid white',
                        boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: 'white',
                        fontWeight: 'bold',
                        fontSize: '12px',
                        transition: 'all 0.2s',
                        zIndex: 10
                      }}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.transform = 'translateY(-50%) scale(1.1)';
                        e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.3)';
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.transform = 'translateY(-50%) scale(1)';
                        e.currentTarget.style.boxShadow = '0 2px 8px rgba(0,0,0,0.2)';
                      }}
                      title={`Weekly tasks: ${weekData?.completedTasks || 0}/${weekData?.totalTasks || 0} (${weekPercentage}%)`}
                    >
                      {weekPercentage}%
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div style={{ marginTop: '30px', padding: '20px', backgroundColor: '#f8f9fa', borderRadius: '8px' }}>
        <h3 style={{ marginBottom: '15px' }}>Legend</h3>
        <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <div style={{ width: '30px', height: '30px', backgroundColor: '#27ae60', borderRadius: '4px' }}></div>
            <span>90-100% Complete</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <div style={{ width: '30px', height: '30px', backgroundColor: '#f39c12', borderRadius: '4px' }}></div>
            <span>50-89% Complete</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <div style={{ width: '30px', height: '30px', backgroundColor: '#e74c3c', borderRadius: '4px' }}></div>
            <span>1-49% Complete</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <div style={{ width: '30px', height: '30px', backgroundColor: '#95a5a6', borderRadius: '4px' }}></div>
            <span>0% Complete</span>
          </div>
        </div>
        <div style={{ marginTop: '15px', color: '#7f8c8d' }}>
          <strong>Daily tasks:</strong> Click on any day to view daily tasks<br/>
          <strong>Weekly tasks:</strong> Click the circle button on the right of each week<br/>
          <strong>Monthly tasks:</strong> Shown in the progress bar above
        </div>
      </div>
    </div>
  );
}

export default CalendarView;
